print(footer[:100])
# Thrift compact protocol reader
class R:
    def __init__(self,b): self.b=b; self.i=0; self.last_type=0; self.last_id=0
    def varint(self):
        v=0; s=0
        while True:
            x=self.b[self.i]; self.i+=1; v|=(x&0x7f)<<s; s+=7
            if not x&0x80: break
        return v
    def zig(self):
        v=self.varint(); return (v>>1) ^ -(v&1)
    def byte(self): x=self.b[self.i]; self.i+=1; return x
    def read_value(self,t):
        # compact types: 0 stop,1 bool true,2 bool false,3 byte,4 i16,5 i32,6 i64,7 double,8 binary,9 list,10 set,11 map,12 struct
        if t in (1,): return True
        if t in (2,): return False
        if t==3:
            x=self.byte(); return x-256 if x>127 else x
        if t in (4,5,6): return self.zig()
        if t==7:
            x=struct.unpack('<d', self.b[self.i:self.i+8])[0]; self.i+=8; return x
        if t==8:
            n=self.varint(); x=self.b[self.i:self.i+n]; self.i+=n; return x
        if t in (9,10):
            h=self.byte(); size=h>>4; et=h&0xf
            if size==15: size=self.varint()
            return [self.read_value(et) for _ in range(size)]
        if t==11:
            size=self.varint()
            if size==0: return {}
            h=self.byte(); kt=h>>4; vt=h&0xf
            return {self.read_value(kt): self.read_value(vt) for _ in range(size)}
        if t==12: return self.read_struct()
        raise Exception(f"type {t} at {self.i}")
    def read_struct(self):
        res={}
        last_id=0
        while True:
            h=self.byte()
            if h==0: break
            delta=h>>4; t=h&0xf
            if delta==0: fid=self.zig()
            else: fid=last_id+delta
            last_id=fid
            res[fid]=self.read_value(t)
        return res
