def _decode_go_string_bytes(b):
    if isinstance(b, str):
        return b
    # decode utf-8 replacing each invalid byte with U+FFFD (approximation of Go)
    out = []
    i = 0
    while i < len(b):
        c = b[i]
        if c < 0x80:
            out.append(chr(c)); i += 1; continue
        # try decode a sequence
        for ln in (2,3,4):
            if i+ln <= len(b):
                try:
                    s = b[i:i+ln].decode('utf-8')
                    if len(s) == 1:
                        out.append(s); i += ln; break
                except Exception:
                    pass
        else:
            out.append('\ufffd'); i += 1; continue
        # if loop broke, continue; if not, handled in else? python for-else tricky:
        # The above for with break skips else; if no break we already appended.
        # Detect whether i advanced: if last appended corresponds, continue
