def _shortest_decimal(f):
    # returns (digits string without dot/sign, decimal exponent e where value = d.ddd *10^e, sign)
    r = repr(float(f))
    # python repr may be like 1e+20, 123.45, 0.001
    if 'e' in r or 'E' in r:
        mant, ex = r.lower().split('e'); ex = int(ex)
        mant = mant.lstrip('-').replace('.', '')
        mant = mant.lstrip('0') or '0'
        # exponent for first digit: mantissa was d.ddd
        return mant, ex
    else:
        neg = r.startswith('-')
        s = r[1:] if neg else r
        if '.' in s:
            ip, fp = s.split('.')
        else:
            ip, fp = s, ''
        digits = (ip + fp).lstrip('0')
        if digits == '':
            return '0', 0
        # compute exponent: position of first digit
        all_digits = ip + fp
        first = next(i for i,c in enumerate(all_digits) if c != '0')
        # value = digits *10^(len(ip)-first-1 - (len(fp))) hmm use exponent of first significant digit
        e = (len(ip) - 1) - first
        digits = digits.rstrip('0') or '0'
        return digits, e

def go_json_float(f):
    if math.isnan(f) or math.isinf(f):
        raise GoJSONUnsupported(f)
    if f == 0:
        return '-0' if math.copysign(1.0, f) < 0 else '0'
    af = abs(f)
    digits, e = _shortest_decimal(f)
    sign = '-' if f < 0 else ''
    if 1e-6 <= af < 1e21:
        # fixed notation
        # digits with decimal point at e+1
        if e >= 0:
            if len(digits) > e+1:
                intpart = digits[:e+1]; frac = digits[e+1:].rstrip('0')
                return sign + intpart + (('.' + frac) if frac else '')
            else:
                return sign + digits + '0'*(e+1-len(digits))
        else:
            return sign + '0.' + '0'*(-e-1) + digits
    else:
        # scientific
        if len(digits) == 1:
            mant = digits
        else:
            mant = digits[0] + '.' + digits[1:]
        return f"{sign}{mant}e{e:+03d}"

def go_v_float(f):
    # Go fmt %v / strconv FormatFloat 'g' -1 behaviour as observed
    if math.isnan(f): return 'NaN'
    if math.isinf(f): return '+Inf' if f>0 else '-Inf'
    if f == 0:
        return '-0' if math.copysign(1.0,f)<0 else '0'
    digits, e = _shortest_decimal(f)
    sign = '-' if f<0 else ''
    if -4 <= e <= 5:
        if e >= 0:
            if len(digits) > e+1:
                return sign + digits[:e+1] + '.' + digits[e+1:]
            else:
                return sign + digits + '0'*(e+1-len(digits))
        else:
            return sign + '0.' + '0'*(-e-1) + digits
    else:
        mant = digits[0] + (('.'+digits[1:]) if len(digits)>1 else '')
        return f"{sign}{mant}e{e:+03d}"

def go_json_dumps(v):
    if v is None: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v, UnknownFloat):
        return go_json_float(float(v))
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, int): return str(v)
    if isinstance(v, float): return go_json_float(v)
    if isinstance(v, (bytes, bytearray)): return go_json_escape_str(bytes(v))
    if isinstance(v, str): return go_json_escape_str(v)
    if isinstance(v, (datetime.datetime, datetime.date)): return go_json_escape_str(_format_time_value(v))
    if isinstance(v, dict):
        return '{' + ','.join(go_json_escape_str(str(k)) + ':' + go_json_dumps(val) for k,val in v.items()) + '}'
    if isinstance(v, (list, tuple)):
        return '[' + ','.join(go_json_dumps(x) for x in v) + ']'
