            ip, fp = s, ''
        digits = (ip + fp).lstrip('0')
        if digits == '':
            return '0', 0
        # compute exponent: position of first digit
        all_digits = ip + fp
        first = next(i for i,c in enumerate(all_digits) if c != '0')
        # value = digits *10^(len(ip)-first-1 - (len(fp))) hmm use exponent of first significant digit
