# ---------- Go JSON decoder ----------
def _go_quote_char(b):
    # b is int byte or a character
    if isinstance(b, str):
        ch=b; o=ord(ch)
    else:
        ch=chr(b); o=b
    if ch=='\'': return "'\\''"
    if ch=='"': return "'\"'"
    if ch=='\n': return "'\\n'"
    if ch=='\r': return "'\\r'"
    if ch=='\t': return "'\\t'"
    if 32 <= o < 127:
        return f"'{ch}'"
    if o < 0x10000:
        return "'\\u%04x'" % o
    return f"'{ch}'"

class GoJSONError(Exception):
    pass

