def parse_float_go(s):
    # Returns float or raises ValueError if Go strconv.ParseFloat would error (excluding range returning value? caller handles)
    orig=s
    if s=='':
        raise ValueError("empty")
    low=s.lower()
    if low in ('inf','+inf','infinity','+infinity'): return math.inf
    if low in ('-inf','-infinity'): return -math.inf
    if low in ('nan','+nan','-nan'): return math.nan
    # underscores: Go permits only between digits (approx): replace _ if between digits/alphanum
    if '_' in s:
        if re.search(r'[^0-9a-zA-Z_.+\-eEpPxX_]', s): raise ValueError("bad")
        # remove underscores that are between alphanumeric chars
        s2=re.sub(r'(?<=[0-9A-Za-z])_(?=[0-9A-Za-z])', '', s)
        if '_' in s2: raise ValueError("underscore")
        s=s2
    # hex float
    if re.match(r'^[+-]?0[xX]', s):
        # Go requires p exponent for hex float
        if not re.search(r'[pP][+-]?\d+$', s): raise ValueError("hex without p")
        try:
            # python fromhex requires hex digits with optional dot
            v=float.fromhex(s)
        except Exception:
            raise ValueError("hex")
        if math.isinf(v): raise ValueError("range")
        return v
    # decimal
    if not re.match(r'^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$', s):
        raise ValueError("not number")
    try:
        v=float(s)
    except Exception:
        raise ValueError("float")
    if math.isinf(v):
        raise ValueError("range")
    return v

