                    # quoted value
                    pos+=1; chars=[]; closed=False
                    while pos<n:
                        c=line[pos]
                        if c=='\\' and pos+1<n:
                            nxt=line[pos+1]
                            # logfmt quoted escapes: \" \\ \n \t etc? Go logfmt uses strconv-style?
                            if nxt=='n': chars.append('\n')
                            elif nxt=='t': chars.append('\t')
                            elif nxt=='r': chars.append('\r')
                            elif nxt=='"': chars.append('"')
                            elif nxt=='\\': chars.append('\\')
                            else: chars.append(nxt)
                            pos+=2; continue
                        if c=='"':
                            closed=True; pos+=1; break
                        chars.append(c); pos+=1
                    if not closed:
                        raise LogfmtError(f"logfmt syntax error at pos {n+1} on line {lineno}: unterminated quoted value")
                    value=''.join(chars)
                else:
                    start_v=pos
                    while pos<n and line[pos] not in ' \t':
                        c=line[pos]
                        if c=='"':
                            raise LogfmtError(f'logfmt syntax error at pos {pos+1} on line {lineno}: unexpected \'"\'')
