    for line in lines:
        if re.match(r'^---($|[ \t])', line):
            if started or cur:
                docs.append(cur)
            cur=[]; started=True
            rest=line[3:].strip()
            if rest:
                cur.append(rest)
        else:
            cur.append(line)
    docs.append(cur)
    # If file began with ---, first doc before is empty in docs list handling above;
    # Our algorithm: if first separator seen, docs may contain a leading empty cur only if there was content before.
