def _col_letter_to_index(letters):
    idx=0
    for ch in letters:
        if 'A'<=ch<='Z': idx=idx*26+(ord(ch)-64)
        elif 'a'<=ch<='z': idx=idx*26+(ord(ch)-96)
        else: break
    return idx-1

def _xlsx_sheet_rows(root, shared, fmt_by_style, NS):
    sheetData=root.find('m:sheetData',NS)
    if sheetData is None: return []
    rows_by_num={}
    max_row_num=0
    sequential_row=0
    for row_elem in sheetData.findall('m:row',NS):
        sequential_row+=1
        r_attr=row_elem.get('r')
        try: rnum=int(r_attr) if r_attr else sequential_row
        except Exception: rnum=sequential_row
        sequential_row=rnum
        cells={}
        max_col=-1
        seq_col=0
        for c in row_elem.findall('m:c',NS):
