        if elem.tag.endswith('}spreadsheet') or elem.tag=='spreadsheet':
            spreadsheet=elem; break
    container=spreadsheet if spreadsheet is not None else root
    for table in container:
        if not (table.tag.endswith('}table') and 'table' in table.tag): # tag includes table:table
