            if not row_elem.tag.endswith('}table-row'): continue
            repeat_row=int(row_elem.get('{urn:oasis:names:tc:opendocument:xmlns:table:1.0}number-rows-repeated','1') or 1)
            cells=[]
            for cell in row_elem:
                if not (cell.tag.endswith('}table-cell') or cell.tag.endswith('}covered-table-cell')): continue
