            # Heuristic: while cells and last=='' and len(cells)>0 and there was a repeat>1 for last cell, we have already expanded, keep as is except cap at 1024
            if len(cells)>1024: cells=cells[:1024]
            for _ in range(min(repeat_row, 10000)):
                rows.append(list(cells))
        sheets.append((name, rows))
    return sheets

def _ods_cell_text(cell):
    paras=[]
    for p in cell:
        if p.tag.endswith('}p'):
            paras.append(_ods_text_of_p(p))
    if not paras:
        # direct text?
        txt=''.join(cell.itertext())
        return txt
    return '\n'.join(paras)

def _ods_text_of_p(p):
    parts=[]
    def walk(elem):
        if elem.text: parts.append(elem.text)
        for child in elem:
            tag=child.tag
            if tag.endswith('}s'):
                cnt=child.get('{urn:oasis:names:tc:opendocument:xmlns:text:1.0}c') or '1'
                try: n=int(cnt)
                except Exception: n=1
                parts.append(' '*n)
            elif tag.endswith('}tab'):
                # original ignores tab element
                pass
            elif tag.endswith('}line-break'):
                parts.append('\n')
            else:
                walk(child)
            if child.tail: parts.append(child.tail)
    walk(p)
    return ''.join(parts)

