class AvroError(Exception):
    pass

class AvroReader:
    def __init__(self, data):
        self.d=data; self.i=0
    def read_long(self):
        val=0; shift=0
        while True:
            if self.i>=len(self.d): raise AvroError("unexpected EOF")
            b=self.d[self.i]; self.i+=1; val|=(b&0x7f)<<shift; shift+=7
            if not (b&0x80): break
        return (val>>1) ^ -(val&1)
    def read_bytes_raw(self, n):
        if self.i+n>len(self.d): raise AvroError("unexpected EOF")
        v=self.d[self.i:self.i+n]; self.i+=n; return v
    def read_len_bytes(self):
        n=self.read_long()
        if n<0: raise AvroError(f"size is negative: {n}")
        return self.read_bytes_raw(n)

