    if isinstance(schema, dict):
        typ=schema.get('type')
        ns=schema.get('namespace', namespace)
        if typ in ('record','enum','fixed') and 'name' in schema:
            full=_avro_fullname(schema['name'], ns, named)
            named[full]=schema
            named[schema['name']]=schema
            namespace=full.rsplit('.',1)[0] if '.' in full else ns
        for v in schema.values():
            _avro_register_named(v, named, ns if isinstance(ns,str) else namespace)
    elif isinstance(schema, list):
        for item in schema: _avro_register_named(item, named, namespace)

def _avro_decode(schema, r, named, namespace=''):
    # returns python value following goavro conventions (unions as {typename: value} except null)
    if isinstance(schema, str):
        if schema in named:
            return _avro_decode(named[schema], r, named, namespace)
        return _avro_decode_primitive(schema, r, named)
    if isinstance(schema, list):
        idx=r.read_long()
        if idx<0 or idx>=len(schema):
            raise AvroError(f"union index out of range: {idx}")
        branch=schema[idx]
        # type name for union key
        if branch=='null' or branch is None:
            _avro_decode(branch, r, named, namespace)
