        return {key: val}
    if isinstance(schema, dict):
        typ=schema.get('type')
        if isinstance(typ, (dict,list)):
            return _avro_decode(typ, r, named, namespace)
        if typ=='record':
            ns=schema.get('namespace', namespace)
            full=_avro_fullname(schema.get('name',''), ns, named) if schema.get('name') else ''
            record_ns=full.rsplit('.',1)[0] if '.' in full else ns
            out={}
            for field in schema.get('fields',[]):
                fname=field['name']
                ftype=field['type']
                out[fname]=_avro_decode(ftype, r, named, record_ns)
            return out
        if typ=='enum':
            idx=r.read_long()
            symbols=schema.get('symbols',[])
            return symbols[idx] if 0<=idx<len(symbols) else ''
        if typ=='fixed':
            size=schema.get('size',0)
            return r.read_bytes_raw(size)
        if typ=='array':
            items=schema.get('items')
            arr=[]
            while True:
                count=r.read_long()
                if count==0: break
                if count<0:
                    _bs=r.read_long(); count=-count
                for _ in range(count): arr.append(_avro_decode(items, r, named, namespace))
            return arr
        if typ=='map':
            values=schema.get('values')
            out={}
            while True:
                count=r.read_long()
                if count==0: break
                if count<0:
                    _bs=r.read_long(); count=-count
                for _ in range(count):
                    k=r.read_len_bytes().decode('utf-8','replace')
                    out[k]=_avro_decode(values, r, named, namespace)
            return out
        # primitive named in dict
        return _avro_decode_primitive(typ, r, named, schema)
    return None

def _avro_union_key(branch, named, namespace):
    if isinstance(branch, str):
        if branch in named:
            s=named[branch]
            if isinstance(s, dict) and 'name' in s:
                ns=s.get('namespace', namespace)
                return _avro_fullname(s['name'], ns, named)
            return branch
        return branch
    if isinstance(branch, dict):
        typ=branch.get('type')
        if typ in ('record','enum','fixed') and 'name' in branch:
            ns=branch.get('namespace', namespace)
            return _avro_fullname(branch['name'], ns, named)
        return str(typ)
    if isinstance(branch, list): return 'union'
    return str(branch)

def _avro_decode_primitive(typ, r, named, schema_dict=None):
    if typ=='null': return None
    if typ=='boolean':
        b=r.read_bytes_raw(1)[0]; return b!=0
    if typ in ('int','long'):
        # logical types handling if schema_dict provided
        val=r.read_long()
        if isinstance(schema_dict, dict):
            lt=schema_dict.get('logicalType')
            if lt=='timestamp-millis':
                return datetime.datetime.fromtimestamp(val/1000, tz=datetime.timezone.utc)
            if lt=='timestamp-micros':
                return datetime.datetime.fromtimestamp(val/1000000, tz=datetime.timezone.utc)
            if lt=='date':
                return datetime.date(1970,1,1)+datetime.timedelta(days=val)
            if lt=='time-millis' or lt=='time-micros':
                return val
        return val
    if typ=='float':
        return struct.unpack('<f', r.read_bytes_raw(4))[0]
    if typ=='double':
        return struct.unpack('<d', r.read_bytes_raw(8))[0]
    if typ=='bytes':
        b=r.read_len_bytes()
        if isinstance(schema_dict, dict) and schema_dict.get('logicalType')=='decimal':
            return b
        return b
    if typ=='string':
        b=r.read_len_bytes()
        return b.decode('utf-8','replace')
    # named reference via dict type string already handled
    if isinstance(typ, str) and typ in named:
        return _avro_decode(named[typ], r, named)
    raise AvroError(f"unknown avro type: {typ}")

