def _decode_rle_bitpacked(data, bit_width, count, offset=0, length=None):
    # RLE/bit-packed hybrid. If length is given, data slice considered that length.
    end = offset+length if length is not None else len(data)
    vals=[]; pos=offset
    if bit_width==0:
        return [0]*count, end
    while len(vals)<count and pos<end:
        # uvarint header
        header=0; shift=0
        while True:
            b=data[pos]; pos+=1; header|=(b&0x7f)<<shift; shift+=7
            if not b&0x80: break
        if header & 1 == 0:
            run=header>>1
            nbytes=(bit_width+7)//8
            v=int.from_bytes(data[pos:pos+nbytes],'little'); pos+=nbytes
            vals.extend([v]*run)
        else:
            groups=header>>1
            total=groups*8
            nbytes=(bit_width*8+7)//8
            chunk=data[pos:pos+ ((bit_width*total+7)//8)]; pos+= (bit_width*total+7)//8
            # unpack LSB first
            acc=0; acc_bits=0; ci=0
            for _ in range(total):
                while acc_bits<bit_width:
                    acc |= chunk[ci] << acc_bits; ci+=1; acc_bits+=8
                mask=(1<<bit_width)-1 if bit_width<64 else (1<<64)-1
                vals.append(acc & mask)
                acc >>= bit_width; acc_bits-=bit_width
    return vals[:count], pos

def _read_rle_levels(data, max_level, count, offset=0, v2_len=None):
    if max_level==0:
        return [0]*count, offset
    bit_width=(max_level).bit_length()
    if v2_len is not None:
        vals,_=_decode_rle_bitpacked(data[offset:offset+v2_len], bit_width, count)
        return vals, offset+v2_len
    else:
        if offset+4>len(data): return [0]*count, offset
        ln=struct.unpack('<i', data[offset:offset+4])[0]; offset+=4
        vals,_=_decode_rle_bitpacked(data[offset:offset+ln], bit_width, count)
        return vals, offset+ln

