class ThriftReader:
    def __init__(self,b): self.b=b; self.i=0
    def varint(self):
        v=0; s=0
        while True:
            x=self.b[self.i]; self.i+=1; v|=(x&0x7f)<<s; s+=7
            if not x&0x80: break
