def _decode_rle_bitpacked(data, bit_width, count, offset=0, length=None):
    # RLE/bit-packed hybrid. If length is given, data slice considered that length.
    end = offset+length if length is not None else len(data)
    vals=[]; pos=offset
    if bit_width==0:
        return [0]*count, end
