            x=struct.unpack('<d', self.b[self.i:self.i+8])[0]; self.i+=8; return x
        if t==8:
            n=self.varint(); x=self.b[self.i:self.i+n]; self.i+=n; return x
        if t in (9,10):
            h=self.byte(); size=h>>4; et=h&0xf
            if size==15: size=self.varint()
            return [self.read_value(et) for _ in range(size)]
        if t==11:
            size=self.varint()
            if size==0: return {}
            h=self.byte(); kt=h>>4; vt=h&0xf
            return [(self.read_value(kt), self.read_value(vt)) for _ in range(size)]
        if t==12: return self.read_struct()
        raise Exception(f"thrift type {t}")
    def read_struct(self):
        res={}; last=0
        while True:
            h=self.byte()
            if h==0: break
            delta=h>>4; t=h&0xf
            fid=self.zig() if delta==0 else last+delta
            last=fid
            res[fid]=self.read_value(t)
        return res

PARQUET_TYPES={0:'BOOLEAN',1:'INT32',2:'INT64',3:'INT96',4:'FLOAT',5:'DOUBLE',6:'BYTE_ARRAY',7:'FIXED_LEN_BYTE_ARRAY'}

def parquet_mangle_name(name):
    # parquet-go name conversion: non alphanumeric/_ replaced by decimal code, prefix if first char not a letter
    out=''
    bs=name.encode('utf-8', 'replace') if any(ord(c)>127 for c in name) else None
    # For ascii names, code per character; for unicode use rune code
    for ch in name:
        if ch.isalnum() and ord(ch)<128 or ch=='_':
            # Actually digits/alnum: letters and digits, underscore stays
            if ch=='_' or ('A'<=ch<='Z') or ('a'<=ch<='z') or ('0'<=ch<='9'):
                out+=ch
            else:
                out+=str(ord(ch))
        else:
            out+=str(ord(ch))
    if name and not (('A'<=name[0]<='Z') or ('a'<=name[0]<='z')):
        out="PARGO_PREFIX_"+out
    return out

def parse_parquet(data):
    # original error for tiny/invalid files: "seek <file>: invalid argument" handled at caller with display name
    if len(data)<12 or data[:4]!=b'PAR1' or data[-4:]!=b'PAR1':
        raise _ParquetSeekError()
    flen=struct.unpack('<i', data[-8:-4])[0]
    if flen<0 or 8+flen>len(data): raise _ParquetSeekError()
    footer=data[len(data)-8-flen:len(data)-8]
    try:
        md=ThriftReader(footer).read_struct()
    except Exception:
        raise _ParquetSeekError()
    schema_list=md.get(2,[])
    if not schema_list: return []
    # build schema tree
    elems=[]
    for e in schema_list:
        elems.append({
            'type': e.get(1), 'type_length': e.get(2), 'repetition': e.get(3,0), 'name': _b2s(e.get(4,b'')),
            'num_children': e.get(5,0), 'converted': e.get(6), 'scale': e.get(7), 'precision': e.get(8), 'logical': e.get(10)
        })
    # Build tree iteratively
    idx=0
    def build():
        nonlocal idx
        el=elems[idx]; idx+=1
        node=dict(el); node['children']=[]
        for _ in range(el['num_children'] or 0):
            node['children'].append(build())
        return node
    root=build()
    leaves=[]
    def collect(node, path, maxdef, maxrep):
        # path excludes root: if root is the schema root (num_children>0 and ... first element is root)
        name=node['name']
        newpath=path+[name] if path or node is not root else []
        # repetition: 0 required,1 optional,2 repeated
        d=maxdef; r=maxrep
        if node is not root:
            if node['repetition']==1: d+=1
            elif node['repetition']==2: d+=1; r+=1
        if not node['children']:
            node['_path']=newpath; node['_maxdef']=d; node['_maxrep']=r
            leaves.append(node)
        else:
            for ch in node['children']: collect(ch, newpath, d, r)
    collect(root, [], 0, 0)
    rows=[]
    row_groups=md.get(4,[])
    for rg in row_groups:
        num_rows_rg=rg.get(3,0)
        col_chunks=rg.get(1,[])
        columns_data=[]
        for ci, leaf in enumerate(leaves):
            if ci < len(col_chunks):
                chunk=col_chunks[ci]
                meta=chunk.get(3,{})
                vals=_parquet_read_column(data, meta, leaf)
            else:
                vals=[None]*num_rows_rg
            columns_data.append(vals)
        # vals may be list entries if repeated; each entry already grouped per row for columns where maxrep>0 by reader
        for r_i in range(num_rows_rg):
            row={}
            for ci, leaf in enumerate(leaves):
                path=leaf['_path']
                display=parquet_mangle_name(path[-1]) if path else parquet_mangle_name(leaf['name'])
                # For nested paths, parquet-go flattens ??? Use mangled last name only for flat schemas
                if len(path)>1:
                    display='.'.join(parquet_mangle_name(p) for p in path)
                val=columns_data[ci][r_i] if r_i < len(columns_data[ci]) else None
                row[display]=val
            rows.append(row)
    return rows

class _ParquetSeekError(Exception):
    pass

def _b2s(b):
    if isinstance(b,bytes): return b.decode('utf-8','replace')
    return str(b)

def _parquet_read_column(data, meta, leaf):
    codec=meta.get(4,0)
    num_values=meta.get(5,0)
    total_comp=meta.get(7,0)
    data_off=meta.get(9)
    dict_off=meta.get(11)
    start=data_off
    if dict_off is not None: start=min(start, dict_off) if start is not None else dict_off
    if start is None: return []
    end=start+total_comp if total_comp else len(data)
    pos=start
    dictionary=None
    all_vals=[] # entries: (def_level, rep_level, value or None marker)
    while pos<end:
        # page header
        try:
            hr=ThriftReader(data[pos:]); hdr=hr.read_struct(); hlen=hr.i
        except Exception:
            break
        page_type=hdr.get(1); comp_size=hdr.get(3,0); uncomp_size=hdr.get(2,0)
        body_start=pos+hlen; body=data[body_start:body_start+comp_size]
        if page_type==2: # dictionary
            dph=hdr.get(7,{})
            n_dict=dph.get(1,0); enc=dph.get(2,0)
            raw=decompress_block_by_codec(codec, body, uncomp_size)
            dictionary=_parquet_decode_plain(raw, leaf, n_dict)
            pos=body_start+comp_size; continue
        elif page_type==0: # data v1
            dph=hdr.get(5,{})
            n_vals=dph.get(1,0); enc=dph.get(2,0)
            raw=decompress_block_by_codec(codec, body, uncomp_size)
            vals=_parquet_decode_data_page_v1(raw, leaf, n_vals, enc, dictionary)
            all_vals.extend(vals)
            pos=body_start+comp_size; continue
        elif page_type==3: # data v2
            dph=hdr.get(8,{})
            n_vals=dph.get(1,0); n_nulls=dph.get(2,0); n_rows=dph.get(3,0); enc=dph.get(4,0)
            def_len=dph.get(5,0); rep_len=dph.get(6,0); is_comp=dph.get(7, True)
            # body: rep levels (uncomp), def levels (uncomp), values (maybe compressed)
            rep_data=body[:rep_len]; def_data=body[rep_len:rep_len+def_len]; val_data=body[rep_len+def_len:]
            if is_comp and codec!=0:
                val_data=decompress_block_by_codec(codec, val_data, uncomp_size-rep_len-def_len)
            vals=_parquet_decode_data_page_v2(rep_data, def_data, val_data, leaf, n_vals, enc, dictionary)
            all_vals.extend(vals)
            pos=body_start+comp_size; continue
        else:
            pos=body_start+comp_size
    # convert entries to per-row values
    return _parquet_entries_to_rows(all_vals, leaf, num_values)

def _parquet_entries_to_rows(entries, leaf, expected):
    maxrep=leaf['_maxrep']; maxdef=leaf['_maxdef']
    if maxrep==0:
        return [v for (d,r,v) in entries]
    # group by rep level 0 starts new row
    rows=[]; cur=None
    for (d,r,v) in entries:
        if r==0:
            if cur is not None: rows.append(cur)
            cur=[]
        if cur is None: cur=[]
        if leaf['_maxdef']>0 and d<maxdef and maxrep>0:
            # null repeated field -> empty list? approximate
            pass
        else:
            cur.append(v)
    if cur is not None: rows.append(cur)
    # If leaf is repeated but rows may expect scalar if... Repeated fields become list
    return rows

def _decode_rle_bitpacked(data, bit_width, count, offset=0, length=None):
    # RLE/bit-packed hybrid. If length is given, data slice considered that length.
    end = offset+length if length is not None else len(data)
    vals=[]; pos=offset
    if bit_width==0:
        return [0]*count, end
    while len(vals)<count and pos<end:
        # uvarint header
        header=0; shift=0
        while True:
            b=data[pos]; pos+=1; header|=(b&0x7f)<<shift; shift+=7
            if not b&0x80: break
        if header & 1 == 0:
            run=header>>1
            nbytes=(bit_width+7)//8
            v=int.from_bytes(data[pos:pos+nbytes],'little'); pos+=nbytes
            vals.extend([v]*run)
        else:
            groups=header>>1
            total=groups*8
            nbytes=(bit_width*8+7)//8
            chunk=data[pos:pos+ ((bit_width*total+7)//8)]; pos+= (bit_width*total+7)//8
            # unpack LSB first
            acc=0; acc_bits=0; ci=0
            for _ in range(total):
                while acc_bits<bit_width:
                    acc |= chunk[ci] << acc_bits; ci+=1; acc_bits+=8
                mask=(1<<bit_width)-1 if bit_width<64 else (1<<64)-1
                vals.append(acc & mask)
                acc >>= bit_width; acc_bits-=bit_width
    return vals[:count], pos

def _read_rle_levels(data, max_level, count, offset=0, v2_len=None):
    if max_level==0:
        return [0]*count, offset
    bit_width=(max_level).bit_length()
    if v2_len is not None:
        vals,_=_decode_rle_bitpacked(data[offset:offset+v2_len], bit_width, count)
        return vals, offset+v2_len
    else:
        if offset+4>len(data): return [0]*count, offset
        ln=struct.unpack('<i', data[offset:offset+4])[0]; offset+=4
        vals,_=_decode_rle_bitpacked(data[offset:offset+ln], bit_width, count)
        return vals, offset+ln

def _parquet_decode_data_page_v1(raw, leaf, n_vals, enc, dictionary):
    maxdef=leaf['_maxdef']; maxrep=leaf['_maxrep']
    pos=0
    rep_levels, pos = _read_rle_levels(raw, maxrep, n_vals, pos) if maxrep>0 else ([0]*n_vals, pos)
    def_levels, pos = _read_rle_levels(raw, maxdef, n_vals, pos) if maxdef>0 else ([0]*n_vals, pos)
    n_present=sum(1 for d in def_levels if d==maxdef) if maxdef>0 else n_vals
    # for repeated fields, present condition is def==maxdef (value) ; if def == maxdef-? repeated empty still no value
    values=[]
    if enc in (2,8): # dictionary
        if pos>=len(raw): bit_width=0
        else: bit_width=raw[pos]; pos+=1
        indices,_=_decode_rle_bitpacked(raw[pos:], bit_width, n_present)
        for ix in indices: values.append(dictionary[ix] if dictionary and 0<=ix<len(dictionary) else None)
    elif enc==0: # PLAIN
        values=_parquet_decode_plain(raw[pos:], leaf, n_present)
    elif enc==5: # DELTA_BINARY_PACKED
        values=_parquet_decode_delta_binary(raw[pos:], n_present)
    elif enc==6: # DELTA_LENGTH_BYTE_ARRAY
        lengths=_parquet_decode_delta_binary(raw[pos:], -1) # need pos... not fully supported; fallback plain byte arrays
        # implement below inline
        values=_parquet_decode_delta_length(raw[pos:], leaf)
    elif enc==7: # DELTA_BYTE_ARRAY
        values=_parquet_decode_delta_byte_array(raw[pos:], leaf, n_present)
    elif enc==9: # BYTE_STREAM_SPLIT
        values=_parquet_decode_byte_stream_split(raw[pos:], leaf, n_present)
    else:
        values=_parquet_decode_plain(raw[pos:], leaf, n_present)
    entries=[]; vi=0
    for i in range(n_vals):
        d=def_levels[i] if i<len(def_levels) else maxdef
        r=rep_levels[i] if i<len(rep_levels) else 0
        if d==maxdef:
            entries.append((d,r, values[vi] if vi<len(values) else None)); vi+=1
        else:
            entries.append((d,r,None))
    return entries

def _parquet_decode_data_page_v2(rep_data, def_data, val_data, leaf, n_vals, enc, dictionary):
    maxdef=leaf['_maxdef']; maxrep=leaf['_maxrep']
    rep_levels,_ = _read_rle_levels(rep_data, maxrep, n_vals, 0, v2_len=len(rep_data)) if maxrep>0 else ([0]*n_vals,0)
    def_levels,_ = _read_rle_levels(def_data, maxdef, n_vals, 0, v2_len=len(def_data)) if maxdef>0 else ([0]*n_vals,0)
    n_present=sum(1 for d in def_levels if d==maxdef) if maxdef>0 else n_vals
    values=[]
    if enc in (2,8):
        if len(val_data)>0:
            bit_width=val_data[0]
            indices,_=_decode_rle_bitpacked(val_data[1:], bit_width, n_present)
            values=[dictionary[ix] if dictionary and 0<=ix<len(dictionary) else None for ix in indices]
    elif enc==0:
        values=_parquet_decode_plain(val_data, leaf, n_present)
    elif enc==5:
        values=_parquet_decode_delta_binary(val_data, n_present)
    elif enc==6:
        values=_parquet_decode_delta_length(val_data, leaf)
    elif enc==7:
        values=_parquet_decode_delta_byte_array(val_data, leaf, n_present)
    elif enc==9:
        values=_parquet_decode_byte_stream_split(val_data, leaf, n_present)
    else:
        values=_parquet_decode_plain(val_data, leaf, n_present)
    entries=[]; vi=0
    for i in range(n_vals):
        d=def_levels[i] if i<len(def_levels) else maxdef
        r=rep_levels[i] if i<len(rep_levels) else 0
        if d==maxdef:
            entries.append((d,r, values[vi] if vi<len(values) else None)); vi+=1
        else:
            entries.append((d,r,None))
    return entries

def _parquet_convert_value(rawval, leaf):
    t=leaf['type']; converted=leaf.get('converted')
    logical=leaf.get('logical')
    # logical is thrift struct dict for LogicalType: field ids: 1 STRING,2 MAP,3 LIST,4 ENUM,5 DECIMAL,6 DATE,7 TIME,8 TIMESTAMP,10 INT,11 UUID etc.
    if t==6: # BYTE_ARRAY
        # string if converted UTF8 (0) or logical STRING
        if converted==0 or (isinstance(logical,dict) and 1 in logical):
            return rawval.decode('utf-8','replace') if isinstance(rawval,bytes) else rawval
        if converted==19: # JSON
            return rawval.decode('utf-8','replace') if isinstance(rawval,bytes) else rawval
        if converted==20: # BSON etc raw
            return rawval
        return rawval.decode('utf-8','replace') if isinstance(rawval,bytes) else rawval
    if t==7:
        if converted==0 or (isinstance(logical,dict) and 1 in logical):
            return rawval.decode('utf-8','replace') if isinstance(rawval,bytes) else rawval
        return rawval
    if t==3: # INT96 -> timestamp nanos: parquet-go returns string? Return integer nanos combined as string ISO approximation
        if isinstance(rawval, tuple):
            nanos, julian = rawval
            # julian day to unix days: unix = julian - 2440588
            days=julian-2440588
            dt=datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)+datetime.timedelta(days=int(days), seconds=int(nanos//1000000000))
            # preserve nanos
            return dt
        return rawval
    if t in (1,2):
        # date/time logical handling: parquet-go generally returns raw integers for these in dsq shapes
        return rawval
    return rawval

def _parquet_decode_plain(raw, leaf, count):
    t=leaf['type']; vals=[]; pos=0
    if count<0: count=0
    if t==0: # BOOLEAN bit packed LSB first
        for i in range(count):
            byte=raw[pos + i//8] if pos+i//8 < len(raw) else 0
            vals.append(bool((byte >> (i%8)) & 1))
        pos += (count+7)//8
    elif t==1:
        for i in range(count):
            vals.append(struct.unpack_from('<i', raw, pos)[0]); pos+=4
    elif t==2:
        for i in range(count):
            vals.append(struct.unpack_from('<q', raw, pos)[0]); pos+=8
    elif t==3:
        for i in range(count):
            nanos=struct.unpack_from('<q', raw, pos)[0]; julian=struct.unpack_from('<i', raw, pos+8)[0]; pos+=12
            vals.append(_parquet_convert_value((nanos,julian), leaf))
    elif t==4:
        for i in range(count):
            vals.append(struct.unpack_from('<f', raw, pos)[0]); pos+=4
    elif t==5:
        for i in range(count):
            vals.append(struct.unpack_from('<d', raw, pos)[0]); pos+=8
    elif t==6:
        for i in range(count):
            if pos+4>len(raw): break
            ln=struct.unpack_from('<i', raw, pos)[0]; pos+=4
            vals.append(_parquet_convert_value(raw[pos:pos+ln], leaf)); pos+=ln
    elif t==7:
        ln=leaf.get('type_length') or 0
        for i in range(count):
            vals.append(_parquet_convert_value(raw[pos:pos+ln], leaf)); pos+=ln
    return vals

def _parquet_delta_reader(data):
    # returns function to read uvarint/zigzag
    state={'i':0}
    def uvarint():
        v=0; s=0; i=state['i']
        while True:
            b=data[i]; i+=1; v|=(b&0x7f)<<s; s+=7
            if not b&0x80: break
        state['i']=i; return v
    def zig():
        v=uvarint(); return (v>>1) ^ -(v&1)
    return uvarint, zig, state

def _parquet_decode_delta_binary(data, count):
    if count==-1: count=None
    uvarint, zig, state = _parquet_delta_reader(data)
    try:
        block_size=uvarint(); miniblocks_per_block=uvarint(); total=uvarint(); first=zig()
    except Exception:
        return []
    if count is None: count=total
    vals=[first]
    # values remaining total-1
    # Each block: min delta (zig), bitwidth byte per miniblock, then values packed
    values_per_miniblock = block_size // miniblocks_per_block if miniblocks_per_block else block_size
    while len(vals)<total:
        min_delta=zig()
        widths=[]
        for _ in range(miniblocks_per_block):
            widths.append(data[state['i']]); state['i']+=1
        for mb in range(miniblocks_per_block):
            if len(vals)>=total: break
            bw=widths[mb]
            n=values_per_miniblock
            if bw==0:
                deltas=[0]*n
            else:
                chunk=data[state['i']: state['i'] + (bw*n+7)//8]
                # advance
                state['i'] += (bw*n+7)//8
                deltas=[]; acc=0; acc_bits=0; ci=0
                for _i in range(n):
                    while acc_bits<bw:
                        if ci < len(chunk): acc|=chunk[ci]<<acc_bits; ci+=1
                        acc_bits+=8
                    deltas.append(acc & ((1<<bw)-1)); acc>>=bw; acc_bits-=bw
            for d in deltas:
                if len(vals)>=total: break
                vals.append(vals[-1] + min_delta + d)
    return vals[:count]

def _parquet_decode_delta_length(data, leaf):
    # lengths encoded delta binary, cannot know count from header alone; try parse first to get total
    # _parquet_decode_delta_binary with count None logic: we call a variant - here decode by reading total from stream
    # Reuse: decode with a large count using internal: parse header manually
    uvarint, zig, state = _parquet_delta_reader(data)
    # Instead, call delta binary with total discovered: we cheat by decoding using function that returns all (pass count as big and let it stop) - use _parquet_decode_delta_binary_all
    vals=_parquet_decode_delta_binary_all(data)
    if not vals: return []
    total=vals[0] if False else None
    lengths=vals
    pos=state['i'] if False else None
    # Need offset after delta-encoded lengths: our all function doesn't return offset. Implement inline here duplicate:
    return _parquet_delta_length_impl(data, leaf)

def _parquet_decode_delta_binary_all(data):
    # decode all ints (knowing total from header)
    uvarint, zig, state = _parquet_delta_reader(data)
    try:
        block_size=uvarint(); miniblocks_per_block=uvarint(); total=uvarint(); first=zig()
    except Exception:
        return []
    vals=[first]
    values_per_miniblock = block_size // miniblocks_per_block if miniblocks_per_block else block_size
    while len(vals)<total:
        min_delta=zig()
        widths=[data[state['i']+k] for k in range(miniblocks_per_block)]; state['i']+=miniblocks_per_block
        for mb in range(miniblocks_per_block):
            if len(vals)>=total: break
            bw=widths[mb]; n=values_per_miniblock
            if bw==0: deltas=[0]*n
            else:
                nbytes=(bw*n+7)//8; chunk=data[state['i']:state['i']+nbytes]; state['i']+=nbytes
                deltas=[]; acc=0; acc_bits=0; ci=0
                for _i in range(n):
                    while acc_bits<bw:
                        acc|=chunk[ci]<<acc_bits; ci+=1; acc_bits+=8
                    deltas.append(acc & ((1<<bw)-1)); acc>>=bw; acc_bits-=bw
            for d in deltas:
                if len(vals)>=total: break
                vals.append(vals[-1]+min_delta+d)
    return vals

def _parquet_delta_length_impl(data, leaf):
    # decode delta ints and remember end offset
    uvarint, zig, state = _parquet_delta_reader(data)
    try:
        block_size=uvarint(); miniblocks_per_block=uvarint(); total=uvarint(); first=zig()
    except Exception: return []
    lengths=[first]
    values_per_miniblock = block_size // miniblocks_per_block if miniblocks_per_block else block_size
    while len(lengths)<total:
        min_delta=zig(); widths=[]
        for _ in range(miniblocks_per_block): widths.append(data[state['i']]); state['i']+=1
        for mb in range(miniblocks_per_block):
            if len(lengths)>=total: break
            bw=widths[mb]; n=values_per_miniblock
            if bw==0: deltas=[0]*n
            else:
                nbytes=(bw*n+7)//8; chunk=data[state['i']:state['i']+nbytes]; state['i']+=nbytes
                deltas=[]; acc=0; acc_bits=0; ci=0
                for _i in range(n):
                    while acc_bits<bw:
                        acc|=chunk[ci]<<acc_bits; ci+=1; acc_bits+=8
                    deltas.append(acc & ((1<<bw)-1)); acc>>=bw; acc_bits-=bw
            for d in deltas:
                if len(lengths)>=total: break
                lengths.append(lengths[-1]+min_delta+d)
    pos=state['i']; vals=[]
    for ln in lengths:
        vals.append(_parquet_convert_value(data[pos:pos+ln], leaf)); pos+=ln
    return vals

def _parquet_decode_delta_byte_array(data, leaf, count):
    prefixes=_parquet_decode_delta_binary(data, count)
    # Need offsets: not trivial; fallback unsupported
    return []

def _parquet_decode_byte_stream_split(data, leaf, count):
    t=leaf['type']; sizes={1:4,2:8,4:4,5:8}
    sz=sizes.get(t)
    if sz is None:
        if t==6 or t==7:
            # lengths are 4 byte streams first?
            return []
        return []
    vals=[]
    for i in range(count):
        bs=bytearray(sz)
        for j in range(sz):
            idx=j*count+i
            bs[j]=data[idx] if idx<len(data) else 0
        if t==1: vals.append(struct.unpack('<i', bytes(bs))[0])
