            if len(txt)>30 or '\n' in txt:
                lines=_wrap_pretty_text(txt)
            else:
                lines=[txt.strip(' ')]
            cells[c]=lines
            if len(lines)>maxlines: maxlines=len(lines)
            for ln in lines:
                w=_display_width(ln)
                if w>widths[c]: widths[c]=w
        prepared_rows.append((cells,maxlines))
    def border():
        return '+' + '+'.join('-'*(widths[c]+2) for c in cols) + '+\n'
    buf=[]
    buf.append(border())
    # header centered
    header_cells=[]
    for c in cols:
        h=str(c).strip(' \t')
        w=widths[c]; extra=w-_display_width(h); left=extra//2; right=extra-left
        header_cells.append(' ' + ' '*left + h + ' '*right + ' ')
    buf.append('|'+'|'.join(header_cells)+'|\n')
    buf.append(border())
    for cells,maxlines in prepared_rows:
        for li in range(maxlines):
            parts=[]
            for c in cols:
                lines=cells[c]
                txt=lines[li] if li<len(lines) else ''
                w=widths[c]
                extra=w-_display_width(txt)
                if _NUMERIC_PRETTY_RE.match(txt):
                    aligned=' '*extra + txt
                else:
                    aligned=txt + ' '*extra
                parts.append(' '+aligned+' ')
            buf.append('|'+'|'.join(parts)+'|\n')
    buf.append(border())
    n=len(rows)
    buf.append(f"({n} row{'s' if n!=1 else ''})\n")
    out.write(''.join(buf).encode('utf-8','replace'))

