# ---------- SQL execution ----------
PLACEHOLDER_RE=re.compile(r'\{(\d*)\}')

def split_sql_statements(sql):
    stmts=[]; cur=''
    # Iterate characters, using sqlite3.complete_statement when a semicolon is seen
    for idx,ch in enumerate(sql):
        cur+=ch
        if ch==';':
            if sqlite3.complete_statement(cur):
                stmts.append(cur); cur=''
    if cur!='':
        stmts.append(cur)
    # Filter? Keep all (including whitespace/comment tails)
    return stmts

def sql_error_text(e):
    msg=str(e)
    # Go sqlite 3.39 quotes table names in "already exists"
    m=re.match(r'^table ([^\s"]+) already exists$', msg)
    if m: msg=f'table "{m.group(1)}" already exists'
    m=re.match(r'^there is already a table named (.+)$', msg)
    # keep as is
    return msg

def _connect_sqlite(path_or_memory):
    if path_or_memory is None:
        con=sqlite3.connect(':memory:')
    else:
        con=sqlite3.connect(path_or_memory)
    con.isolation_level=None
    con.text_factory=lambda b: b.decode('utf-8','replace') if isinstance(b,(bytes,bytearray)) else b
    return con

def _quote_ident(name):
    return '"' + str(name).replace('"','""') + '"'

def _temp_columns_for_file(lf):
    # returns list of (name, path, type, leaf shape) or raises DSQError if not array of objects
    v=lf.value
    if not isinstance(v, list):
        raise DSQError(f"Input is not an array of objects: {lf.display_name}.")
    shape=lf.shape
    if shape is None or shape[0]!='array' or shape[1][0]!='object':
        raise DSQError(f"Input is not an array of objects: {lf.display_name}.")
    obj_shape=shape[1]
    cols=flatten_shape_columns(obj_shape)
    # sort by display name bytes (matches CREATE TABLE generation in original)
    cols_sorted=sorted(cols, key=lambda x: x[0].encode('utf-8'))
    return [(name,path,column_type_for_shape(leaf),leaf) for name,path,leaf in cols_sorted]

def _extract_path(row, path):
    cur=row
    for key in path:
        if isinstance(cur, dict) and key in cur:
            cur=cur[key]
        else:
            return None
    return cur

def _value_for_db(val, leaf_shape):
    # Convert a flattened value for insertion
    if val is None: return None
    if isinstance(val, dict) or isinstance(val, (list,tuple)):
        try: return go_json_dumps(val)
        except GoJSONUnsupported as e: raise DSQError(f"json: unsupported value: {e.msg}")
    if isinstance(val, bool): return 1 if val else 0
    if isinstance(val, UnknownFloat):
        # For a TEXT column, SQLite will convert; for REAL etc it is a float
        return float(val)
    if isinstance(val, (datetime.datetime, datetime.date)):
        return _format_time_value(val)
    return val

def _create_shape_table(con, lf, idx, temp=True, log_create=True):
    cols=_temp_columns_for_file(lf)
    if log_create: log_info(f"Creating table t_{idx}")
    coldefs=', '.join(f"{_quote_ident(name)} {typ}" for name,path,typ,leaf in cols)
    # Original SQL: CREATE TEMP TABLE "t_0" ("a" REAL) / CREATE TABLE (cache) has space before ()
    # SQLite syntax error for empty columns replicates "near )"
    table=_quote_ident(f"t_{idx}")
    if temp:
        sql=f'CREATE TEMP TABLE {table} ({coldefs})'
    else:
        sql=f'CREATE TABLE {table} ({coldefs})'
    try:
        con.execute(sql)
    except sqlite3.Error as e:
        raise DSQError(sql_error_text(e))
    if cols:
        placeholders=','.join('?' for _ in cols)
        colnames=','.join(_quote_ident(c[0]) for c in cols)
        # Use temp/main table name unqualified (temp shadows)
        insert_sql=f"INSERT INTO {table} ({colnames}) VALUES ({placeholders})"
        for row in lf.value:
            if not isinstance(row, dict): continue
            vals=[]
            for name,path,typ,leaf in cols:
                raw=_extract_path(row, path)
                vals.append(_value_for_db(raw, leaf))
            try: con.execute(insert_sql, vals)
            except sqlite3.Error as e: raise DSQError(sql_error_text(e))
    return cols

def _create_delimited_table(con, lf, idx, convert_numbers=False, use_numeric=False):
    rows=lf.delimited_raw_rows
    if not rows: return []
    cols=list(rows[0].keys())
    coltype='NUMERIC' if use_numeric else 'TEXT'
    coldefs=','.join(f"{_quote_ident(c)} {coltype}" for c in cols)
    table=_quote_ident(f"t_{idx}")
    try: con.execute(f'CREATE TABLE {table}({coldefs})')
    except sqlite3.Error as e: raise DSQError(sql_error_text(e))
    if cols:
        insert_sql=f"INSERT INTO {table} ({','.join(_quote_ident(c) for c in cols)}) VALUES ({','.join('?' for _ in cols)})"
        for row in rows:
            vals=[row.get(c) for c in cols]
            try: con.execute(insert_sql, vals)
            except sqlite3.Error as e: raise DSQError(sql_error_text(e))
    return cols

class QueryRunner:
    def __init__(self, files, convert_numbers=False, schema_mode=False, cache_con=None, cache_invalid=False, persistent_con=None, engine_override=None, bool_cols=None):
        self.files=files
        self.convert_numbers=convert_numbers
        self.schema_mode=schema_mode
        self.cache_con=cache_con
        self.cache_invalid=cache_invalid
        self.persistent_con=persistent_con
        self.engine_override=engine_override
        self.bool_cols=set(bool_cols) if bool_cols else set()
        self._owns_con=True
    def _is_all_delimited(self):
        return len(self.files)>0 and all(f.is_delimited for f in self.files)
    def use_shape_engine(self, query_text):
        if self.schema_mode: return True
        if self.engine_override=='shape': return True
        if self.engine_override=='delimited': return False
        return not self._is_all_delimited()
    def run(self, query_text):
        # returns (rows as list[dict], columns list)
        shape_engine=self.use_shape_engine(query_text)
        # analyze placeholders in whole query
        matches=list(PLACEHOLDER_RE.finditer(query_text))
        referenced=[]
        seen=set()
        for m in matches:
            idx=int(m.group(1)) if m.group(1)!='' else 0
            if idx not in seen:
                seen.add(idx); referenced.append(idx)
        # out-of-range panic logic
        if shape_engine:
            for idx in referenced:
                if idx<0 or idx>=len(self.files):
                    panic_out_of_range(idx, len(self.files))
        con=None; owns=True
        if self.persistent_con is not None:
            con=self.persistent_con; owns=False
            # On persistent con, shape tables are created per-run (temp), delimited assumed already created
            if shape_engine:
                for idx in referenced:
                    cols=_create_shape_table(con, self.files[idx], idx, temp=True)
                    for name,path,typ,leaf in cols:
                        if typ=='BOOLEAN': self.bool_cols.add(name)
            # run on this connection
            rows, cols = self._execute_on_connection(con, query_text, shape_engine, referenced)
            return rows, cols
        if self.cache_con is not None:
            con=self.cache_con
            if self.cache_invalid:
                if shape_engine:
                    for idx in referenced:
                        cols=_create_shape_table(con, self.files[idx], idx, temp=False)
                        for name,path,typ,leaf in cols:
                            if typ=='BOOLEAN': self.bool_cols.add(name)
                else:
                    for i,lf in enumerate(self.files):
                        _create_delimited_table(con, lf, i, self.convert_numbers, use_numeric=self.convert_numbers)
            else:
                # populate bool cols from cache tables
                try:
                    for tinfo in con.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall():
                        tname=tinfo[0]
                        for cinfo in con.execute(f"PRAGMA table_info({_quote_ident(tname)})").fetchall():
                            if (cinfo[2] or '').upper()=='BOOLEAN': self.bool_cols.add(cinfo[1])
                except Exception: pass
            rows, cols=self._execute_on_connection(con, query_text, shape_engine, referenced)
            return rows, cols
        # fresh connection
        if shape_engine:
            con=_connect_sqlite(None)
            for idx in referenced:
                cols=_create_shape_table(con, self.files[idx], idx, temp=True)
                for name,path,typ,leaf in cols:
                    if typ=='BOOLEAN': self.bool_cols.add(name)
        else:
            # delimited: use a temp file db to mirror original pragma database_list
            tmpdir=os.environ.get('TMPDIR','/tmp')
            rand=''.join(random.choice('0123456789') for _ in range(10))
            dbpath=os.path.join(tmpdir, f"dsq-sqlite-shared{rand}")
            try: con=_connect_sqlite(dbpath)
            except Exception: con=_connect_sqlite(None)
            con._dsq_tmp_path=dbpath
            for i,lf in enumerate(self.files):
                _create_delimited_table(con, lf, i, self.convert_numbers, use_numeric=self.convert_numbers)
        try:
            rows, cols=self._execute_on_connection(con, query_text, shape_engine, referenced)
            return rows, cols
        finally:
            if con is not None:
                try: con.close()
                except Exception: pass
                p=getattr(con,'_dsq_tmp_path',None)
                if p:
                    try: os.remove(p)
                    except Exception: pass
    def _execute_on_connection(self, con, query_text, shape_engine, referenced):
        # replacement
