def _hash_for_cache(file_entries_with_raw):
    # file_entries: list of (display, raw_or_none_for_real)
    h=hashlib.sha1()
    for display, raw in file_entries_with_raw:
        if raw is None:
            # try read
            if os.path.isdir(display):
                raise DSQError(f"read {display}: is a directory")
            try:
                with open(display,'rb') as f: data=f.read()
            except FileNotFoundError:
                raise DSQError(f"open {display}: no such file or directory")
            except IsADirectoryError:
                raise DSQError(f"read {display}: is a directory")
            except PermissionError:
                raise DSQError(f"open {display}: permission denied")
        else:
            data=raw
        h.update(data)
    return h.hexdigest()

