                sys.stderr.write("EOF\n"); exit_code=1; break
            except KeyboardInterrupt:
                sys.stderr.write("\n"); continue
        else:
            raw=sys.stdin.buffer.readline()
            if raw==b'':
                sys.stderr.write("EOF\n"); exit_code=1; break
            line=raw.decode('utf-8','replace')
            if line.endswith('\n'): line=line[:-1]
            if line.endswith('\r'): line=line[:-1]
        # record history (if line non-empty raw length>0)
        if line!='':
            try:
                with open(hist_path,'a',encoding='utf-8') as hf: hf.write(line+"\n")
            except Exception: pass
            if readline_mod is not None:
                try: readline_mod.add_history(line)
                except Exception: pass
        stripped=line.strip()
        if stripped=='':
            continue
        if stripped=='exit':
            out.write(b"bye\n"); out.flush(); exit_code=0; break
        # run query
        try:
            result=runner.run(line)
            _format_output_for_query(result, True, schema, out)
            out.flush()
        except PanicError as e:
            sys.stderr.write(e.text); 
            if con is not None:
                try: con.close()
                except Exception: pass
            return 2
        except DSQError as e:
            sys.stderr.write(e.text)
            if con is not None:
                try: con.close()
                except Exception: pass
            return e.code
    if con is not None:
        try: con.close()
        except Exception: pass
    return exit_code

