    vals=[];acc=0;bits=0;idx=0
    for _ in range(count):
        while bits<width: acc=(acc<<8)|data[idx];idx+=1;bits+=8
        shift=bits-width; vals.append((acc>>shift)&((1<<width)-1)); acc&=(1<<shift)-1 if shift else 0; bits=shift
    return vals
def unpack_lsb(data,width,count):
    vals=[];acc=0;bits=0;idx=0
    for _ in range(count):
        while bits<width: acc|=data[idx]<<bits;idx+=1;bits+=8
        vals.append(acc&((1<<width)-1)); acc>>=width; bits-=width
    return vals

